(3052969, 429633, 29269, '<td valign="top">This one had a potential in this challenge, but unfortunately it is too small for adequate valuation.</td>', 'This one had a potential in this challenge, but unfortunately it is too small for adequate valuation.', '2006-11-22 01:47:37.000000', NULL, 1),
(3052985, 429984, 51660, '<td valign="top">This I would hang on my wall. Very nice.</td>', 'This I would hang on my wall. Very nice.', '2006-11-22 01:51:25.000000', NULL, 1),
(3052989, 428846, 29269, '<td valign="top">360x240 is too small for just evaluation. Please use the full available size next time.<br/>Other than that, shallow DOF makes it harder to fit into the perspective challenge. It can be used to reduce the effect of the bacground and augment the foreground object. Your object is a fork, viewed from the side (the least interesting aspect of a fork), and the blurred remote area fights for attention with the boring fork, and does not provide the viewer with enjoyment.<br/> <br/>Better luck next time.</td>', '360x240 is too small for just evaluation. Please use the full available size next time.Other than that, shallow DOF makes it harder to fit into the perspective challenge. It can be used to reduce the effect of the bacground and augment the foreground object. Your object is a fork, viewed from the side (the least interesting aspect of a fork), and the blurred remote area fights for attention with the boring fork, and does not provide the viewer with enjoyment. Better luck next time.', '2006-11-22 01:51:51.000000', NULL, 1),
(3052996, 428610, 67324, '<td valign="top">Nice. Good angle and pick of tree. Ideal balance for a square crop. 7</td>', 'Nice. Good angle and pick of tree. Ideal balance for a square crop. 7', '2006-11-22 01:53:01.000000', NULL, 1),
