(3054238, 429307, 66727, '<td valign="top">Great colors! 9</td>', 'Great colors! 9', '2006-11-22 11:30:15.000000', NULL, 1),
(3054239, 429880, 66727, '<td valign="top">Nice perspective</td>', 'Nice perspective', '2006-11-22 11:30:35.000000', NULL, 1),
(3054246, 428387, 68256, '<td valign="top">I don''t really get "Perspective of a minority"....He is in line with the others like he has the same views as them.  I mean really, what are you trying to say?  Sure he is a minority in color and shape but not in perspective.  Also, the white balance seems way off....</td>', 'I don''t really get "Perspective of a minority"....He is in line with the others like he has the same views as them.  I mean really, what are you trying to say?  Sure he is a minority in color and shape but not in perspective.  Also, the white balance seems way off....', '2006-11-22 11:31:58.000000', NULL, 1),
