(3054253, 430197, 68256, '<td valign="top">It is very warm and inviting...makes me want to proceed.</td>', 'It is very warm and inviting...makes me want to proceed.', '2006-11-22 11:33:29.000000', NULL, 1),
(3054260, 430270, 51538, '<td valign="top">Nicely found image.  It would make a great stock shot since the guy is dressed in shirt and tie.. 7.</td>', 'Nicely found image.  It would make a great stock shot since the guy is dressed in shirt and tie.. 7.', '2006-11-22 11:35:19.000000', NULL, 1),
