(3058223, 429815, 68504, '<td valign="top">Gutsy.</td>', 'Gutsy.', '2006-11-23 19:58:08.000000', NULL, 1),
(3058231, 430441, 68504, '<td valign="top">Arresting contrast of dark shapes against all the reds and blues, but maybe too many shapes (branchlets midway along dock)?  Still, its something to look at.</td>', 'Arresting contrast of dark shapes against all the reds and blues, but maybe too many shapes (branchlets midway along dock)?  Still, its something to look at.', '2006-11-23 20:02:39.000000', NULL, 1),
