(3061678, 429975, 66597, '<td valign="top">I love the idea, and the face is perfectly focused. I''m not wild on the background, though, especially the flare/highlights. 6.</td>', 'I love the idea, and the face is perfectly focused. I''m not wild on the background, though, especially the flare/highlights. 6.', '2006-11-25 16:55:21.000000', NULL, 1),
(3061682, 428686, 66597, '<td valign="top">Because only part of the glass is showing and in focus, it is hard to move into this photo. Consider with a larger crop maybe?</td>', 'Because only part of the glass is showing and in focus, it is hard to move into this photo. Consider with a larger crop maybe?', '2006-11-25 16:56:07.000000', NULL, 1),
(3061684, 430281, 66597, '<td valign="top">So pretty with magical lighting. Wish the frontmost fence post were in focus. 7.</td>', 'So pretty with magical lighting. Wish the frontmost fence post were in focus. 7.', '2006-11-25 16:56:37.000000', NULL, 1),
