(3061687, 429931, 66597, '<td valign="top">Simple and pretty, with sharp focus.</td>', 'Simple and pretty, with sharp focus.', '2006-11-25 16:57:27.000000', NULL, 1),
(3061689, 429815, 66597, '<td valign="top">Is this HDR? Really beautiful colors and textures, though it looks a bit fake to me. 7.</td>', 'Is this HDR? Really beautiful colors and textures, though it looks a bit fake to me. 7.', '2006-11-25 16:57:57.000000', NULL, 1),
(3061691, 429897, 66597, '<td valign="top">I like that you flipped this photo 180. Adds interest.</td>', 'I like that you flipped this photo 180. Adds interest.', '2006-11-25 16:58:18.000000', NULL, 1),
(3061698, 427888, 66597, '<td valign="top">You had a great idea for this shot. I think the high contrast (taken in midday, perhaps?) distracts from the lines. I''d love to see a re-take on a cloudy day with warming filter or under sunny conditions with less contrast.</td>', 'You had a great idea for this shot. I think the high contrast (taken in midday, perhaps?) distracts from the lines. I''d love to see a re-take on a cloudy day with warming filter or under sunny conditions with less contrast.', '2006-11-25 16:59:58.000000', NULL, 1),
(3061699, 428589, 66597, '<td valign="top">Great colors and emotive.</td>', 'Great colors and emotive.', '2006-11-25 17:00:19.000000', NULL, 1),
(3061701, 430337, 66597, '<td valign="top">Very cool, very sharp. Great whites.</td>', 'Very cool, very sharp. Great whites.', '2006-11-25 17:00:40.000000', NULL, 1),
