(3061707, 428570, 66597, '<td valign="top">Great capture. Maybe up the contrast or adjust the colors a little fo brighter whites and more natural sky tone.</td>', 'Great capture. Maybe up the contrast or adjust the colors a little fo brighter whites and more natural sky tone.', '2006-11-25 17:02:57.000000', NULL, 1),
(3061711, 429266, 66597, '<td valign="top">The head being cut off on the subject chess piece is distracting.</td>', 'The head being cut off on the subject chess piece is distracting.', '2006-11-25 17:03:40.000000', NULL, 1),
(3061714, 430245, 66597, '<td valign="top">Nice use of colors to break up monotone.</td>', 'Nice use of colors to break up monotone.', '2006-11-25 17:04:07.000000', NULL, 1),
