(3061935, 430468, 51660, '<td valign="top">Fun idea and good execution!</td>', 'Fun idea and good execution!', '2006-11-25 19:10:58.000000', NULL, 1),
(3062063, 428662, 51538, '<td valign="top">What a wonderful Maurice Escher type of image.  The forms, stairs, and view are magnificent. 9.</td>', 'What a wonderful Maurice Escher type of image.  The forms, stairs, and view are magnificent. 9.', '2006-11-25 21:09:56.000000', NULL, 1),
(3062064, 430235, 51538, '<td valign="top">Your photo certainly draws my eye into the picture. 9.</td>', 'Your photo certainly draws my eye into the picture. 9.', '2006-11-25 21:10:01.000000', NULL, 1),
(3062065, 430376, 51538, '<td valign="top">Subtle and lovely.  I like the tint. 9.</td>', 'Subtle and lovely.  I like the tint. 9.', '2006-11-25 21:10:07.000000', NULL, 1),
(3062066, 429544, 51538, '<td valign="top">Nice angle and colours.  9.</td>', 'Nice angle and colours.  9.', '2006-11-25 21:10:12.000000', NULL, 1),
(3062067, 427677, 51538, '<td valign="top">I love the high contrast and moody feeling. 8.</td>', 'I love the high contrast and moody feeling. 8.', '2006-11-25 21:10:17.000000', NULL, 1),
(3062068, 428745, 51538, '<td valign="top">Simple but effective - pity about that barge and crane though. 8.</td>', 'Simple but effective - pity about that barge and crane though. 8.', '2006-11-25 21:10:24.000000', NULL, 1),
(3062070, 429880, 51538, '<td valign="top">I like the composition and the way the track heads off round the bend.  Might well have been much nicer in a duotone rendition or black and white. 8.</td>', 'I like the composition and the way the track heads off round the bend.  Might well have been much nicer in a duotone rendition or black and white. 8.', '2006-11-25 21:10:35.000000', NULL, 1),
(3062071, 429908, 51538, '<td valign="top">Yours is an exciting composition and not one that is easy to photograph.  The way you alternated the translucent and transparent pieces works well for the viewer.  The brick wall in the background might have been better hidden.  I can''t quite figure out from which direction the lighting is coming. 8 for creative thinking.</td>', 'Yours is an exciting composition and not one that is easy to photograph.  The way you alternated the translucent and transparent pieces works well for the viewer.  The brick wall in the background might have been better hidden.  I can''t quite figure out from which direction the lighting is coming. 8 for creative thinking.', '2006-11-25 21:10:57.000000', NULL, 1),
(3062072, 428705, 51538, '<td valign="top">Simple and effective. 8.</td>', 'Simple and effective. 8.', '2006-11-25 21:11:01.000000', NULL, 1),
(3062074, 429307, 51538, '<td valign="top">Very nice natural perspective therein. 8.</td>', 'Very nice natural perspective therein. 8.', '2006-11-25 21:11:05.000000', NULL, 1),
(3062075, 429925, 51538, '<td valign="top">Not voted all yet - but this idea also occurred to me and I think you have executed it very well. 8.</td>', 'Not voted all yet - but this idea also occurred to me and I think you have executed it very well. 8.', '2006-11-25 21:11:15.000000', NULL, 1),
(3062076, 428836, 51538, '<td valign="top">Nicely curved in a straight-line sort of challenge. 8.</td>', 'Nicely curved in a straight-line sort of challenge. 8.', '2006-11-25 21:11:50.000000', NULL, 1),
(3062077, 430323, 51538, '<td valign="top">Nicely 45 degrees left.  I thought Texas was all about being right.  Well done. 8.</td>', 'Nicely 45 degrees left.  I thought Texas was all about being right.  Well done. 8.', '2006-11-25 21:12:00.000000', NULL, 1),
(3062078, 430363, 51538, '<td valign="top">Very nice composition and focus point. 8.</td>', 'Very nice composition and focus point. 8.', '2006-11-25 21:12:05.000000', NULL, 1),
(3062079, 430246, 51538, '<td valign="top">Very satisfying natural looking composition. 8.</td>', 'Very satisfying natural looking composition. 8.', '2006-11-25 21:12:09.000000', NULL, 1),
(3062080, 430337, 51538, '<td valign="top">Startling in its simplicity. 8.</td>', 'Startling in its simplicity. 8.', '2006-11-25 21:12:13.000000', NULL, 1),
(3062081, 428156, 51538, '<td valign="top">Like a surreal Max Ernst collage image.  Nice work. 8.</td>', 'Like a surreal Max Ernst collage image.  Nice work. 8.', '2006-11-25 21:12:19.000000', NULL, 1),
(3062082, 430459, 51538, '<td valign="top">Nicely rustic and arid in presentation.  The textures are pleasant. 8.</td>', 'Nicely rustic and arid in presentation.  The textures are pleasant. 8.', '2006-11-25 21:12:25.000000', NULL, 1),
(3062083, 429089, 51538, '<td valign="top">Perfectly pleasing geometrical disappearing point therein.  As muted as the colours are, I wonder if a black and white rendition might be better? 8.</td>', 'Perfectly pleasing geometrical disappearing point therein.  As muted as the colours are, I wonder if a black and white rendition might be better? 8.', '2006-11-25 21:12:42.000000', NULL, 1),
(3062084, 428448, 51538, '<td valign="top">Nicely soft image in more ways than one. 8.</td>', 'Nicely soft image in more ways than one. 8.', '2006-11-25 21:12:47.000000', NULL, 1),
(3062086, 430281, 51538, '<td valign="top">I like the location and the rain and the grey sky.  The rough sea and pier are nice too.  But I find it hard to get a focal point in the picture.  The domes of the pier are what attracts my eye. 7.</td>', 'I like the location and the rain and the grey sky.  The rough sea and pier are nice too.  But I find it hard to get a focal point in the picture.  The domes of the pier are what attracts my eye. 7.', '2006-11-25 21:14:15.000000', NULL, 1),
(3062089, 429962, 51538, '<td valign="top">One of the nicest images in the contest. 8.</td>', 'One of the nicest images in the contest. 8.', '2006-11-25 21:14:37.000000', NULL, 1),
(3062108, 429814, 33947, '<td valign="top">Wow, sharp and vivid. Nice positioning and crop. 8</td>', 'Wow, sharp and vivid. Nice positioning and crop. 8', '2006-11-25 21:28:01.000000', NULL, 1),
(3062109, 429954, 68828, '<td valign="top">I can''t figure out what I am looking at, but it''s cool!  Reminds me of M. C. Escher</td>', 'I can''t figure out what I am looking at, but it''s cool!  Reminds me of M. C. Escher', '2006-11-25 21:28:25.000000', NULL, 1),
