(3068213, 429815, 67006, '<td valign="top">This photo is amazing.  I need to know more about how this was processed.  Excellent!</td>', 'This photo is amazing.  I need to know more about how this was processed.  Excellent!', '2006-11-28 12:14:56.000000', NULL, 1),
(3068216, 430270, 67006, '<td valign="top">Having a man dressed as though for work really makes this photo simmer!  One of my top favorites for this challenge!</td>', 'Having a man dressed as though for work really makes this photo simmer!  One of my top favorites for this challenge!', '2006-11-28 12:16:10.000000', NULL, 1),
