INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3069858, 430337, 24528, '<td valign="top">Congrats on ribbon</td>', 'Congrats on ribbon', '2006-11-29 00:13:59.000000', NULL, 0),
(3069859, 428359, 53814, '<td valign="top">Stunning work - demontrates your diverse creativity. Congratulations.</td>', 'Stunning work - demontrates your diverse creativity. Congratulations.', '2006-11-29 00:14:04.000000', NULL, 0),
(3069860, 428584, 52449, '<td valign="top">Very cool! Congratulations on your 6+ score!</td>', 'Very cool! Congratulations on your 6+ score!', '2006-11-29 00:14:05.000000', NULL, 0),
(3069863, 428359, 24528, '<td valign="top">Congrat on ribbon..</td>', 'Congrat on ribbon..', '2006-11-29 00:14:26.000000', NULL, 0),
(3069868, 428359, 8891, '<td valign="top">Heck of job, Les! Love the perspective and the great tones! Many congrats on your ribbon!</td>', 'Heck of job, Les! Love the perspective and the great tones! Many congrats on your ribbon!', '2006-11-29 00:14:52.000000', NULL, 0),
(3069869, 430262, 52449, '<td valign="top">Nice attention to detail, Cindi (referring to your ducky). Great score...congrats! BTW, did you "pimp Lexi''s eyes?" LOL!!<br/><br/><i>Message edited by author 2006-11-29 00:16:42.</i></td>', 'Nice attention to detail, Cindi (referring to your ducky). Great score...congrats! BTW, did you "pimp Lexi''s eyes?" LOL!!', '2006-11-29 00:15:14.000000', '2006-11-29 00:16:42.000000', 0),
(3069870, 430166, 24528, '<td valign="top">Beautiful...Congrats</td>', 'Beautiful...Congrats', '2006-11-29 00:15:17.000000', NULL, 0),
(3069872, 428156, 41337, '<td valign="top">As posthumous said, cool. Congrats!</td>', 'As posthumous said, cool. Congrats!', '2006-11-29 00:15:36.000000', NULL, 0),
(3069873, 430337, 61654, '<td valign="top">What a cool shot. So sharp. Congrats.</td>', 'What a cool shot. So sharp. Congrats.', '2006-11-29 00:15:38.000000', NULL, 0),
(3069880, 429678, 41337, '<td valign="top">Now that''s interesting. I think I like this better than the postcard version.</td>', 'Now that''s interesting. I think I like this better than the postcard version.', '2006-11-29 00:16:30.000000', NULL, 0),
(3069883, 430337, 24495, '<td valign="top">Congrats on reaching new heights!</td>', 'Congrats on reaching new heights!', '2006-11-29 00:16:55.000000', NULL, 0),
(3069888, 430469, 14620, '<td valign="top">Cool!!  8th place for both of us.  You got a better score though. :)</td>', 'Cool!!  8th place for both of us.  You got a better score though. :)', '2006-11-29 00:18:01.000000', NULL, 0),
(3069892, 430415, 31399, '<td valign="top">well your 5.7371 certainly beats my submissions! proud of you as always and I really like the colorful fun feeling I get when I look at this picture!</td>', 'well your 5.7371 certainly beats my submissions! proud of you as always and I really like the colorful fun feeling I get when I look at this picture!', '2006-11-29 00:18:35.000000', NULL, 0),
(3069898, 430472, 5585, '<td valign="top">Good Job, Milos</td>', 'Good Job, Milos', '2006-11-29 00:19:00.000000', NULL, 0),
(3069903, 428359, 30861, '<td valign="top">Wonderful! I''m SO glad this idiosyncratic, compelling image made it into the ribbon ranks! WTG, Lesley!</td>', 'Wonderful! I''m SO glad this idiosyncratic, compelling image made it into the ribbon ranks! WTG, Lesley!', '2006-11-29 00:19:49.000000', NULL, 0),
(3069906, 430103, 5585, '<td valign="top">Cool Shot, Bob</td>', 'Cool Shot, Bob', '2006-11-29 00:20:10.000000', NULL, 0),
(3069913, 430337, 30861, '<td valign="top">Congrats on your blue, Mr. Nico Blue!</td>', 'Congrats on your blue, Mr. Nico Blue!', '2006-11-29 00:20:41.000000', NULL, 0),
(3069922, 430166, 30861, '<td valign="top">Fantastic! A primo example of how the little things mean so much; imagine the image without the people on the bluff... Scale (or perspective) is everything here! Congrats on your ribbon.</td>', 'Fantastic! A primo example of how the little things mean so much; imagine the image without the people on the bluff... Scale (or perspective) is everything here! Congrats on your ribbon.', '2006-11-29 00:22:03.000000', NULL, 0),
(3069925, 429815, 60862, '<td valign="top">Congrats, Robert!  Great shot and high place!</td>', 'Congrats, Robert!  Great shot and high place!', '2006-11-29 00:22:45.000000', NULL, 0),
(3069933, 428156, 30861, '<td valign="top">This image certainly suits your name to a "T" :-) If you asked me to select the best image of "planet making" from the DPC archives, this might be it... I''d love to hear some details of how this was done, specifically the lighting.</td>', 'This image certainly suits your name to a "T" :-) If you asked me to select the best image of "planet making" from the DPC archives, this might be it... I''d love to hear some details of how this was done, specifically the lighting.', '2006-11-29 00:24:30.000000', NULL, 0),
(3069938, 429755, 60862, '<td valign="top">Whoosh is right - got me by 1/10000th of a point. :)<br/> <br/>Nice shot and congrats on breaking the top 31! ;)</td>', 'Whoosh is right - got me by 1/10000th of a point. :) Nice shot and congrats on breaking the top 31! ;)', '2006-11-29 00:25:26.000000', NULL, 0),
(3069939, 430323, 30861, '<td valign="top">Nice work, Yanko! If you''d asked me, I''d have thought it would bomb as well; so what do we know? Not much! Congrats on top 10.</td>', 'Nice work, Yanko! If you''d asked me, I''d have thought it would bomb as well; so what do we know? Not much! Congrats on top 10.', '2006-11-29 00:25:34.000000', NULL, 0),
(3069943, 429609, 31399, '<td valign="top">woooooooohoooooooooooooo Hanae!!! we have been telling you, and reminding you of how talented you are!!!  Very nice score...and great for the team, also...  AWESOME!!!!!!!!!</td>', 'woooooooohoooooooooooooo Hanae!!! we have been telling you, and reminding you of how talented you are!!!  Very nice score...and great for the team, also...  AWESOME!!!!!!!!!', '2006-11-29 00:26:27.000000', NULL, 0),
